import json
import os

async def execute(self, inputs):
    plan_file = str(inputs.get('plan_file') or '').strip()
    if not plan_file:
        self.log_error('[LoadPlan] plan_file path is required.')
        return {'operations_json': '[]', 'intent': '', 'op_count': 0, 'ok': False, 'exec_out': True}

    if not os.path.isfile(plan_file):
        self.log_error(f'[LoadPlan] File not found: {plan_file}')
        return {'operations_json': '[]', 'intent': '', 'op_count': 0, 'ok': False, 'exec_out': True}

    try:
        with open(plan_file, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception as e:
        self.log_error(f'[LoadPlan] Failed to read {plan_file}: {e}')
        return {'operations_json': '[]', 'intent': '', 'op_count': 0, 'ok': False, 'exec_out': True}

    # Accept {ok, intent, operations:[...]} wrapper OR a bare [...] array
    if isinstance(data, list):
        operations = data
        intent = ''
    elif isinstance(data, dict):
        operations = data.get('operations', [])
        intent = str(data.get('intent', ''))
    else:
        self.log_error(f'[LoadPlan] Unexpected JSON root type: {type(data).__name__}')
        return {'operations_json': '[]', 'intent': '', 'op_count': 0, 'ok': False, 'exec_out': True}

    if not isinstance(operations, list):
        self.log_error('[LoadPlan] operations field is not a list.')
        return {'operations_json': '[]', 'intent': intent, 'op_count': 0, 'ok': False, 'exec_out': True}

    self.log_info(f'[LoadPlan] Loaded {len(operations)} operation(s) from {os.path.basename(plan_file)}')
    if intent:
        self.log_info(f'[LoadPlan] Intent: {intent}')

    return {
        'operations_json': json.dumps(operations),
        'intent':          intent,
        'op_count':        len(operations),
        'ok':              True,
        'exec_out':        True,
    }

def register_node():
    from src.nodes.base import BaseNode
    class Hou_Mcp_Load_Plan(BaseNode):
        name = 'hou_mcp_load_plan'
        async def execute(self, inputs):
            return await execute(self, inputs)
    return Hou_Mcp_Load_Plan
